.wordmark-dot{color:var(--accent)}
.mark{display:flex;gap:3px;margin-right:12px;align-items:center;transform:rotate(-16deg)}
.mark i{display:block;width:4px;height:22px;background:var(--accent)}
.mark i:nth-child(2){height:30px}
.header-note{font-size:12px;color:var(--muted);margin-left:auto}
.contact-link{font-size:13px;border:1px solid #657079;border-radius:30px;padding:12px 19px;margin-left:28px}
.contact-link span{padding-left:23px;color:var(--accent)}
.studio-layout{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.35fr);gap:74px;padding:69px 0 62px}
.introduction{padding-top:6px;display:flex;flex-direction:column;align-items:flex-start}
.eyebrow{text-transform:uppercase;letter-spacing:1.8px;font-size:10px;font-weight:600;line-height:1.6;margin:0}
.introduction>.eyebrow{color:var(--accent);display:flex;align-items:center;gap:9px}
.status-dot{width:6px;height:6px;border-radius:50%;background:var(--accent)}
h1{font-family:Georgia,'Times New Roman',serif;font-weight:400;font-size:clamp(43px,4.15vw,62px);line-height:1.09;letter-spacing:-2.2px;margin:34px 0 25px}
h1 span{color:var(--accent)}
.intro-copy{color:var(--muted);font-size:15px;line-height:1.85;max-width:310px;margin:0}
.text-link{font-size:11px;margin-top:29px;padding-bottom:9px;border-bottom:1px solid #56606a;line-height:1.7}
.text-link span{color:var(--accent);padding-left:13px}
.intro-bottom{margin-top:auto;padding-top:72px;display:flex;gap:15px;align-items:center}
.small-cross{font-size:31px;font-weight:300;color:var(--accent)}
.intro-bottom p{font-size:11px;color:var(--muted);line-height:1.7;margin:0}
.features{display:grid;gap:17px}
.feature-card{border:1px solid var(--line);border-radius:3px;background:var(--card);padding:24px 27px 19px;overflow:hidden}
.card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
.card-top .eyebrow{color:var(--accent);font-size:9px}
.card-tag{font-size:9px;color:var(--muted);border:1px solid var(--line);border-radius:20px;padding:5px 9px;white-space:nowrap}
.card-body{display:flex;gap:20px;align-items:center;justify-content:space-between;margin:23px 0 21px}
h2{font-family:Georgia,'Times New Roman',serif;font-weight:400;font-size:29px;letter-spacing:-.7px;margin:0 0 10px;line-height:1.2}
.card-copy{max-width:345px}
.card-copy p{color:var(--muted);font-size:12px;line-height:1.85;margin:0}
.card-foot{border-top:1px solid var(--line);padding-top:13px;font-size:9px;color:var(--muted);margin:0;letter-spacing:.3px;line-height:1.7}
.card-foot span{padding:0 7px;color:#677881}
.diagram{position:relative;width:88px;height:83px;flex-shrink:0;margin-right:3px}
.diagram-thread span{position:absolute;left:4px;top:9px;width:74px;height:53px;border:1px solid #65716f;border-radius:50%;transform:rotate(-38deg)}
.diagram-thread span:nth-child(2){transform:rotate(22deg)}
.diagram-thread span:nth-child(3){transform:rotate(82deg);border-color:var(--accent)}
.diagram-thread b{position:absolute;background:var(--accent);width:7px;height:7px;border-radius:50%;left:39px;top:32px}
.diagram-blocks{display:grid;grid-template-columns:30px 30px;grid-template-rows:30px 30px;gap:7px;justify-content:center;align-content:center;transform:rotate(-8deg)}
.diagram-blocks span{border:1px solid #65716f;border-radius:2px}
.diagram-blocks span:nth-child(2){background:var(--accent);border-color:var(--accent);transform:translate(5px,-5px)}
.diagram-orbit span{position:absolute;width:70px;height:70px;border:1px solid #65716f;border-radius:50%;top:5px;left:2px}
.diagram-orbit span:nth-child(2){width:48px;height:48px;top:16px;left:13px;border-color:var(--accent)}
.diagram-orbit b{position:absolute;width:9px;height:9px;background:var(--accent);border:3px solid var(--card);box-sizing:content-box;border-radius:50%;top:3px;left:49px}
.contact{display:flex;align-items:center;justify-content:space-between;gap:35px;padding:37px 0 39px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.contact .eyebrow{font-size:9px;color:var(--muted);margin-bottom:12px}
.contact h2{font-size:23px;max-width:420px;margin:0}
.email-link{color:var(--accent);font-size:14px;white-space:nowrap;padding-bottom:7px;border-bottom:1px solid #776448}
.email-link span{padding-left:20px}
footer{display:flex;justify-content:space-between;gap:20px;padding:26px 0 31px;font-size:10px;color:var(--muted)}
.skip-link{position:absolute;top:-100px;left:20px;background:var(--accent);color:var(--background);padding:12px;z-index:2}
.skip-link:focus{top:15px}
.skip-link:hover{color:var(--background)}
@media(min-width:1400px){.studio-layout{gap:110px}}
@media(max-width:1000px){.page{padding:0 32px}.studio-layout{gap:36px;grid-template-columns:minmax(230px,.8fr) minmax(0,1.35fr)}.feature-card{padding:20px}.diagram{width:74px;transform:scale(.85);margin-right:-5px}.card-body{gap:10px}.card-tag{font-size:8px}h1{font-size:45px}}
@media(max-width:760px){.page{padding:0 24px}.site-header{height:90px}.header-note{display:none}.contact-link{margin-left:auto}.studio-layout{grid-template-columns:1fr;gap:38px;padding:43px 0}.introduction{max-width:480px}h1{font-size:54px;margin-top:26px}.intro-copy{max-width:370px}.intro-bottom{display:none}.card-copy{max-width:440px}.card-body{gap:20px}.diagram{margin:0 10px}.contact{align-items:flex-start;flex-direction:column;gap:25px}.contact h2{font-size:26px}footer{flex-wrap:wrap;line-height:1.6}footer span:nth-child(2){display:none}}
@media(max-width:380px){.page{padding:0 18px}h1{font-size:47px}.feature-card{padding:19px 16px}.card-tag{display:none}.diagram{width:59px;margin-right:0;transform:scale(.75);transform-origin:left center}.card-body{gap:6px}h2{font-size:26px}.card-foot{font-size:8px}.card-foot span{padding:0 4px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

