from html.parser import HTMLParser
from pathlib import Path
import re
root=Path('output')
class Check(HTMLParser):
 def __init__(self):
  super().__init__(); self.ids=set(); self.links=[]; self.styles=[]; self.stack=[]
 def handle_starttag(self, tag, attrs):
  a=dict(attrs)
  if 'id' in a:
   assert a['id'] not in self.ids, 'Duplicate id'
   self.ids.add(a['id'])
  if tag=='a': self.links.append(a.get('href',''))
  if tag=='link': self.styles.append(a['href'])
  assert tag not in ('script','img','iframe'), 'Unexpected external asset element'
  if tag not in ('meta','link','br','hr','input','img'): self.stack.append(tag)
 def handle_endtag(self, tag):
  assert self.stack.pop()==tag, f'Mismatched tag: {tag}'
p=Check(); html=(root/'index.html').read_text(); p.feed(html)
assert not p.stack
for link in p.links:
 if link.startswith('#') and len(link)>1: assert link[1:] in p.ids
for style in p.styles: assert (root/style).is_file()
css=(root/'style.css').read_text()
assert css.count('{')==css.count('}')
assert not re.search(r'https?://|@import|url\\s*\\(',html+css)
for value in ['#101b28','#eef4ed','#f4b860']: assert value in css
assert 'Quiet systems,' in html and 'clear decisions' in html
assert html.count('class=\"feature-card\"')==3
assert '@media' in css and 'viewport' in html
print('PASS: HTML tag nesting, unique IDs, internal links, local stylesheet, design palette and heading, three cards, responsive rules, and no remote assets or requests.')
for f in sorted(root.iterdir()): print(f'{f}: {f.stat().st_size:,} bytes')
